export function encodePath(points){let lat=0,lng=0;const encode=n=>{let v=n<0?~(n<<1):n<<1,s='';while(v>=32){s+=String.fromCharCode((32|(v&31))+63);v>>=5;}return s+String.fromCharCode(v+63);};return points.map(([a,b])=>{const y=Math.round(a*1e5),x=Math.round(b*1e5),s=encode(y-lat)+encode(x-lng);lat=y;lng=x;return s;}).join('');}
export const points=[[25,-100],[25,-99.999],[25.001,-99.999],[25.001,-99.998]];
export const navigationRoute={distanceMeters:320,durationSeconds:50,polyline:encodePath(points),waypoints:[{lat:25,lng:-100,type:"origin",label:"Origen de prueba"},{lat:25.001,lng:-99.998,type:"destination",label:"Destino de prueba"}],sections:[{actions:[{instruction:"Sal del origen",geometryStart:0,geometryEnd:1},{instruction:"Gira a la izquierda",geometryStart:1,geometryEnd:2},{instruction:"Gira a la derecha",geometryStart:2,geometryEnd:3},{instruction:"Llegada",geometryStart:3,geometryEnd:3}]}]};
